    if (params.get("returnTo") !== "clients" || !data?.items?.length || paymentHistoryClient) return;
    const clientKey = params.get("paymentClientId");
    const client = (data.items as Client[]).find((row) => String(row.id) === clientKey || String(row.clientId ?? "") === clientKey);
    if (client) setPaymentHistoryClient(client);
