    <div className="hidden"><Stat label="Total clients" value={data?.total.toString() ?? "—"} icon={<CheckCircle2 className="h-5 w-5" />} /><Stat label="Active clients" value={data ? items.filter((client) => statusFor(client) === "Active").length.toString() : "—"} icon={<CheckCircle2 className="h-5 w-5" />} /><Stat label="Active students" value={data?.summary.students.toLocaleString("en-IN") ?? "—"} icon={<UsersRound className="h-5 w-5" />} /><Stat label="Total value" value={data ? money(data.summary.value) : "—"} icon={<Download className="h-5 w-5" />} /></div>
